%[text] # BEV System Model - Simulation Case
modelName = "BEV_system_model";
load_system(modelName)
BEV_useThermal %[output:20d90686]
VehSpdRef_loadCase_Constant( ... %[output:group:8e8ebe9d] %[output:262fd18e]
  ModelName = modelName, ... %[output:262fd18e]
  TargetSubsystemPath = "/Controller & Environment/Vehicle speed reference") %[output:group:8e8ebe9d] %[output:262fd18e]
simOut = sim(modelName);
simData = extractTimetable(simOut.logsout);
fig = BEV_ResultsCompactPlot(SimData = simData); %[output:47bdddc0]
